INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('094a7b48-158e-545e-b521-e540b7b6ccab'::uuid, '55fd11c7-0e9a-59b0-bb07-0c8f4f31ed66'::uuid, 'Projet les RESIDENCES – Tamesna ALEM', 'Programme: Electrification MT BT et éclairage publique du Projet construction d’un ensemble immobilier Nom: Les Résidences Lieu: Tamesna Maitre d''Œuvre: ALEM Année: 2019 Durée: 04 mois Budget: 3 425 925,00 MAD', '["https://lechantier.ma/uploads/media/3ba3e4c8d326.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/3ba3e4c8d326.webp', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '3.2.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('6e323ef0-bd17-5282-8d83-b64dafb3ac61'::uuid, '55fd11c7-0e9a-59b0-bb07-0c8f4f31ed66'::uuid, 'BEFRA - marrakech ALEM', 'Programme: Travaux d’électrification et transfert des installations militaires Nom: BEFRA Lieu: Marrakech Maitre d''Œuvre: ALEM Année: 2018 Durée: 04 mois Budget: 3 240 135,00 MAD', '[]'::jsonb, NULL, 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '3.2.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('17bf538d-dfdf-5295-8258-6c54417b745f'::uuid, '9885005d-0dd7-513a-b574-9d181c3b1ad3'::uuid, 'Hnagar AUTOPLUS', 'L’installation électrique du hangar comprend une alimentation à partir d’un transformateur 20 kVA, raccordé à un tableau général (TGBT). La distribution est réalisée en câbles protégés, avec des circuits dédiés pour l’éclairage, les prises et les équipements. L’éclairage est assuré par des projecteurs LED et des blocs de secours.', '["https://lechantier.ma/uploads/media/7dd6f8ecac67.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/7dd6f8ecac67.webp', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '3.2.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('b7347970-3b78-534b-b121-3dbec8fbc9e3'::uuid, '9885005d-0dd7-513a-b574-9d181c3b1ad3'::uuid, 'Villa Nassim Casablanca', 'L’intervention consiste à installer les tableaux électriques principaux et divisionnaires de la villa, comprenant la distribution des circuits d’éclairage, prises, climatisation et équipements spécifiques. Les protections (disjoncteurs, différentiels) sont mises en place selon les normes en vigueur, avec une mise à la terre complète.', '["https://lechantier.ma/uploads/media/3fa065bf314f.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/3fa065bf314f.webp', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '3.2.1' LIMIT 1));
