INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('8018ca62-2a50-53db-b1d2-7b63660fc274'::uuid, '2ef6b5ea-6aa8-5440-978e-3b3693191788'::uuid, 'BAYTI SAKANE', 'BAYTI SAKANE nous a fait confiance pour l’installation de la fibre optique et des réseaux télécom dans ses projets à Mohammedia, Kénitra, Casablanca (Riad Oulfa et Sidi Moumen) et Bouskoura Oasis. Nous avons assuré le déploiement FTTH et une connectivité fiable pour l’ensemble des résidences.', '["https://lechantier.ma/uploads/media/a83115781e55.webp", "https://lechantier.ma/uploads/media/d04283bdedd6.webp", "https://lechantier.ma/uploads/media/cdbb92d3beb2.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/a83115781e55.webp', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '3.2.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('023975cb-5b43-5459-b600-1610d338c06a'::uuid, '2ef6b5ea-6aa8-5440-978e-3b3693191788'::uuid, 'ASSAFOI RESIDENCES', 'Assafoi Résidences à Dar Bouazza nous a confié l’installation de la fibre optique et du réseau télécom au sein de l’ensemble du projet. Nous avons réalisé le déploiement complet du FTTH, du raccordement aux habitations jusqu’à la mise en place des équipements offrant une connectivité fiable et durable.', '["https://lechantier.ma/uploads/media/c33c9728df50.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/c33c9728df50.webp', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '3.2.1' LIMIT 1));
