INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('cc62c661-a639-5d17-a866-6f225d53fae9'::uuid, '6b462917-da5b-51b5-90fe-2f6a58438246'::uuid, 'Inara Solaire', 'تُعدّ INARA SOLAIRE شركة مغربية رائدة في تقديم حلول الطاقة الشمسية المتكاملة، حيث نُقدّم خدمات شاملة تشمل: - الدراسات التقنية والمالية - تركيب الأنظمة الشمسية: سواء كانت متصلة بالشبكة (On-Grid) أو مستقلة عنها (Off-Grid)، - حلول ضخ المياه بالطاقة الشمسية: pompage solaire - 📧 البريد:[\[email protected\]](https://lechantier.ma/cdn-cgi/l/email-protection) - 📞 الهاتف 0637547578', '["https://lechantier.ma/uploads/media/0b286ff8b3f9.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/0b286ff8b3f9.webp', 'Agadir', (SELECT id FROM public.internal_categories WHERE code = '3.2.1' LIMIT 1));
