INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('edce1a32-80a3-57d1-97bd-3ce1e0fa44bf'::uuid, 'f8d17819-6fc0-5650-b41d-d3e3aacad069'::uuid, 'HOTEL TRID AGADIR', 'Installation complète en courant fort pour l’alimentation des équipements électriques (éclairage, prises, appareils), et en courant faible pour la communication (téléphone, internet, interphone, vidéosurveillance), avec câblage, gaines, tableau, mise à la terre et conformité aux normes.', '["https://lechantier.ma/uploads/media/603678fd44fc.webp", "https://lechantier.ma/uploads/media/42081e057393.webp", "https://lechantier.ma/uploads/media/f0f3acd7daf3.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/603678fd44fc.webp', 'Agadir', (SELECT id FROM public.internal_categories WHERE code = '3.2.1' LIMIT 1));
