INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('641e32c4-5819-5b7a-8d4c-39d602d60663'::uuid, 'c2753a23-6d7f-5cd2-8509-2baf0ba81d87'::uuid, 'restaurants et café', 'J’ai réalisé l’installation électrique complète dans un restaurant et un café. Mon travail comprenait la pose des câbles, l’installation des tableaux électriques, des disjoncteurs, des prises de courant, de l’éclairage intérieur et extérieur, ainsi que le raccordement des équipements électriques spécifiques comme les fours, les réfrigérateurs, les', '["https://lechantier.ma/uploads/media/5ee58410abb9.webp", "https://lechantier.ma/uploads/media/4c74154cbd38.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/5ee58410abb9.webp', 'Martil', (SELECT id FROM public.internal_categories WHERE code = '3.2.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('5353ef09-0081-5b38-93aa-e38fae5371f2'::uuid, 'c2753a23-6d7f-5cd2-8509-2baf0ba81d87'::uuid, 'Boulangerie', 'J’ai réalisé l’installation électrique complète dans un Boulangeri . Mon travail comprenait la pose des câbles, l’installation des tableaux électriques, des disjoncteurs, des prises de courant, de l’éclairage intérieur et extérieur, ainsi que le raccordement des équipements électriques spécifiques comme les fours, les réfrigérateurs, etc', '["https://lechantier.ma/uploads/media/b39c5a489dc3.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/b39c5a489dc3.webp', 'Martil', (SELECT id FROM public.internal_categories WHERE code = '3.2.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('25dd5c22-23e8-5508-a0d3-c6cb97d16db6'::uuid, 'c2753a23-6d7f-5cd2-8509-2baf0ba81d87'::uuid, 'Réalisation — sudnordplaning.sarl', NULL, '["https://lechantier.ma/uploads/media/4c74154cbd38.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/4c74154cbd38.webp', 'Martil', (SELECT id FROM public.internal_categories WHERE code = '3.2.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('2bb80f17-4010-55c3-a005-47e5a220fb7b'::uuid, 'e765266d-2263-5a2c-a473-826e50b5b73a'::uuid, 'Villa California : solaire 12 kWc', 'Il s’agit d’une installation solaire photovoltaïque hybride de 12 kWc réalisée pour une villa à California, Casablanca, intégrant un système de stockage. Cette solution assure autonomie énergétique, réduction notable de la facture d’électricité et continuité d’alimentation même en cas de coupure. Une installation clé en main, fiable, durable et con', '["https://lechantier.ma/uploads/media/d4045ea5d4cf.webp", "https://lechantier.ma/uploads/media/b0930d4965be.webp", "https://lechantier.ma/uploads/media/a06e5a02a41f.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/d4045ea5d4cf.webp', 'Morocco', (SELECT id FROM public.internal_categories WHERE code = '3.2.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('023b16c5-e98e-5c58-8b12-2fc4c6af26ce'::uuid, 'e765266d-2263-5a2c-a473-826e50b5b73a'::uuid, 'Installation solaire 15 kWc – Injection', 'Il s’agit d’une installation solaire photovoltaïque de 15 kWc avec injection réseau, pour optimiser la production d’électricité. Solution clé en main, fiable et conforme aux normes, garantissant performance, économie d’énergie et partenariat avec un prestataire compétent.', '["https://lechantier.ma/uploads/media/25be27f1f1d6.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/25be27f1f1d6.webp', 'Morocco', (SELECT id FROM public.internal_categories WHERE code = '3.2.1' LIMIT 1));
