INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('29cc9bb4-18a9-5816-85aa-9b5ae866626f'::uuid, '5f955bc1-906c-5a86-a4e5-ab0e09eae58b'::uuid, 'nous accompagnons nos clients à chaque étape de leur projet : audit, conception, installation,', 'formation et maintenance. Notre réseau de références s''étend au-delà du Maroc, sur plusieurs marchés internationaux,', '["https://allsecure.ma/wp-content/uploads/2023/09/cropped-Design-sans-titre-1-1-150x150.png"]'::jsonb, 'https://allsecure.ma/wp-content/uploads/2023/09/cropped-Design-sans-titre-1-1-150x150.png', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '8.6.3' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('22208d23-316b-5b23-b3f1-cdd5ce0054a7'::uuid, 'af303bea-f916-5974-a45c-287aa1780fd9'::uuid, 'Voir toutes nos réalisations (94 photos)', 'Villas et grands chantiers Baies en double hauteur, garde-corps sur piscine, façades vitrées, carports : nous prenons en charge tout le lot menuiserie aluminium et vitrage des villas de la région. <img src="https://images.aluglass.ma/realisations/facades-vitrees/facade-villa-baie-angle-vitree-etage-rabat-480.webp" srcset="https://images.aluglass.ma/realisations/facades-vit', '["https://images.aluglass.ma/realisations/garde-corps-verre/garde-corps-verre-escalier-marbre-claustra-villa-rabat-480.webp"]'::jsonb, 'https://images.aluglass.ma/realisations/garde-corps-verre/garde-corps-verre-escalier-marbre-claustra-villa-rabat-480.webp', 'Rabat', (SELECT id FROM public.internal_categories WHERE code = '8.5.4' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('d02ff817-ba99-5b54-aa7f-97e1e35a443c'::uuid, 'af303bea-f916-5974-a45c-287aa1780fd9'::uuid, 'Villas et grands chantiers', 'Ce que disent nos clients ★★★★★ 4,9 /5 , d''après 54 avis publiés sur Google. ★★★★★ 5 sur 5 Monsieur Ali et son équipe sont des professionnels de haut niveau. Ils m&#39;ont créé une cuisine hybride (structure en aluminium et portes en MDF). Le résultat est de très bonne qualité ! En plus, monsieur Ali se distingue par sa gentillesse, son sens de l&#39;éco', '["https://images.aluglass.ma/realisations/garde-corps-verre/garde-corps-verre-escalier-marbre-claustra-villa-rabat.webp"]'::jsonb, 'https://images.aluglass.ma/realisations/garde-corps-verre/garde-corps-verre-escalier-marbre-claustra-villa-rabat.webp', 'Rabat', (SELECT id FROM public.internal_categories WHERE code = '8.5.4' LIMIT 1));
