INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('61953f9d-8a71-5a37-940e-b9ea683c4725'::uuid, '5a1380e6-57f2-5803-bc6a-ac415d895478'::uuid, 'Nos réalisations.', 'Andalous Design intervient sur les plus grands monuments historiques du Royaume — palais, mosquées, médersas, mausolées, musées, portes monumentales, jardins, murailles et hammams. Nos équipes œuvrent en collaboration avec les principales institutions nationales et locales, dans le respect de l’authenticité des lieux, des techniques traditionnelles et des exigences de la conservation du patrimoine', '["https://andalousdesign.ma/_next/image?url=%2Fimages%2Fhome%2Fouverture-v3.jpg&w=480&q=75"]'::jsonb, 'https://andalousdesign.ma/_next/image?url=%2Fimages%2Fhome%2Fouverture-v3.jpg&w=480&q=75', 'Fès', (SELECT id FROM public.internal_categories WHERE code = '3.1.5' LIMIT 1));
